bool casadi_nlp_f0(ipindex n, ipnumber *x, bool new_x, ipnumber *obj_value, UserDataPtr user_data) {
  struct casadi_ipopt_data* d = (struct casadi_ipopt_data*) user_data;
  d->arg[0] = x;
  d->arg[1] = d->nlp->p;
  d->res[0] = obj_value;
  if (casadi_f7(d->arg, d->res, d->iw, d->w, 0)) return false;
  return true;
}
bool casadi_nlp_g0(ipindex n, ipnumber *x, bool new_x, ipindex m, ipnumber *g, UserDataPtr user_data) {
  struct casadi_ipopt_data* d = (struct casadi_ipopt_data*) user_data;
  d->arg[0] = x;
  d->arg[1] = d->nlp->p;
  d->res[0] = g;
  if (casadi_f9(d->arg, d->res, d->iw, d->w, 0)) return false;
  return true;
}
bool casadi_nlp_grad_f0(ipindex n, ipnumber *x, bool new_x, ipnumber *grad_f, UserDataPtr user_data) {
  struct casadi_ipopt_data* d = (struct casadi_ipopt_data*) user_data;
  d->arg[0] = x;
  d->arg[1] = d->nlp->p;
  d->res[0] = 0;
  d->res[1] = grad_f;
  if (casadi_f8(d->arg, d->res, d->iw, d->w, 0)) return false;
  return true;
}
bool casadi_nlp_jac_g0(ipindex n, ipnumber *x, bool new_x, ipindex m, ipindex nele_jac, ipindex *iRow, ipindex *jCol, ipnumber *values, UserDataPtr user_data) {
  struct casadi_ipopt_data* d = (struct casadi_ipopt_data*) user_data;
  if (values) {
    d->arg[0] = x;
    d->arg[1] = d->nlp->p;
    d->res[0] = 0;
    d->res[1] = values;
    if (casadi_f10(d->arg, d->res, d->iw, d->w, 0)) return false;
  } else {
    casadi_ipopt_sparsity(d->prob->sp_a, iRow, jCol);
  }
  return true;
}
bool casadi_nlp_hess_l0(ipindex n, ipnumber *x, bool new_x, ipnumber obj_factor,ipindex m, ipnumber *lambda, bool new_lambda, ipindex nele_hess, ipindex *iRow, ipindex *jCol, ipnumber *values, UserDataPtr user_data) {
  struct casadi_ipopt_data* d = (struct casadi_ipopt_data*) user_data;
  if (values) {
    d->arg[0] = x;
    d->arg[1] = d->nlp->p;
    d->arg[2] = &obj_factor;
    d->arg[3] = lambda;
    d->res[0] = values;
    if (casadi_f14(d->arg, d->res, d->iw, d->w, 0)) return false;
    return true;
  } else {
    casadi_ipopt_sparsity(d->prob->sp_h, iRow, jCol);
  }
  return true;
}
/* solver:(x0[246],p[278],lbx[246],ubx[246],lbg[206],ubg[206],lam_x0[246],lam_g0[206])->(x[246],f,g[206],lam_x[246],lam_g[206],lam_p[278]) */
static int casadi_f1(const casadi_real** arg, casadi_real** res, casadi_int* iw, casadi_real* w, int mem) {
  const casadi_real one=1;
  struct casadi_ipopt_data* d=&casadi_f1_mem[mem];
  struct casadi_ipopt_prob p;
  struct casadi_nlpsol_data d_nlp;
  struct casadi_nlpsol_prob p_nlp;
  d_nlp.p = arg[1];
  d_nlp.lbx = arg[2];
  d_nlp.ubx = arg[3];
  d_nlp.lbg = arg[4];
  d_nlp.ubg = arg[5];
  d_nlp.x0 = arg[0];
  d_nlp.lam_x0 = arg[6];
  d_nlp.lam_g0 = arg[7];
  d_nlp.x = res[0];
  d_nlp.f = res[1];
  d_nlp.g = res[2];
  d_nlp.lam_x = res[3];
  d_nlp.lam_g = res[4];
  d_nlp.lam_p = res[5];
  d_nlp.prob = &p_nlp;
  p_nlp.nx = 246;
  p_nlp.ng = 206;
  p_nlp.np = 278;
  p_nlp.detect_bounds.ng = 0;
  casadi_nlpsol_init(&d_nlp, &arg, &res, &iw, &w);
  if (d_nlp.x0) {
    casadi_copy(d_nlp.x0, 246, d_nlp.z);
  } else {
    casadi_clear(d_nlp.z, 246);
  }
  if (d_nlp.lbx) {
    casadi_copy(d_nlp.lbx, 246, d_nlp.lbz);
  } else {
    casadi_fill(d_nlp.lbz, 246, -casadi_inf);
  }
  if (d_nlp.ubx) {
    casadi_copy(d_nlp.ubx, 246, d_nlp.ubz);
  } else {
    casadi_fill(d_nlp.ubz, 246, casadi_inf);
  }
  if (d_nlp.lam_x0) {
    casadi_copy(d_nlp.lam_x0, 246, d_nlp.lam);
  } else {
    casadi_clear(d_nlp.lam, 246);
  }
  if (d_nlp.lbg) {
    casadi_copy(d_nlp.lbg, 206, d_nlp.lbz+246);
  } else {
    casadi_fill(d_nlp.lbz+246, 206, -casadi_inf);
  }
  if (d_nlp.ubg) {
    casadi_copy(d_nlp.ubg, 206, d_nlp.ubz+246);
  } else {
    casadi_fill(d_nlp.ubz+246, 206, casadi_inf);
  }
  if (d_nlp.lam_g0) {
    casadi_copy(d_nlp.lam_g0, 206, d_nlp.lam+246);
  } else {
    casadi_clear(d_nlp.lam+246, 206);
  }
  d->nlp = &d_nlp;
  d->prob = &p;
  p.nlp = &p_nlp;
  p.sp_a = casadi_s26;
  p.sp_h = casadi_s60;
  casadi_ipopt_setup(&p);
  p.eval_f = casadi_nlp_f0;
  p.eval_g = casadi_nlp_g0;
  p.eval_grad_f = casadi_nlp_grad_f0;
  p.eval_jac_g = casadi_nlp_jac_g0;
  p.eval_h = casadi_nlp_hess_l0;
  casadi_ipopt_init(d, &arg, &res, &iw, &w);
  casadi_ipopt_presolve(d);
  AddIpoptIntOption(d->ipopt, "print_level",0);
  AddIpoptStrOption(d->ipopt, "linear_solver","mumps");
  casadi_ipopt_solve(d);
  d->arg[0] = d_nlp.z;
  d->arg[1] = d_nlp.p;
  d->arg[2] = &one;
  d->arg[3] = d_nlp.lam+246;
  d->res[0] = 0;
  d->res[1] = 0;
  d->res[2] = 0;
  d->res[3] = d_nlp.lam_p;
  if (casadi_f2(d->arg, d->res, d->iw, d->w, 0)) return 1;
  casadi_scal(278, -1.0, d_nlp.lam_p);
  casadi_copy(d_nlp.z, 246, d_nlp.x);
  casadi_copy(d_nlp.z + 246, 206, d_nlp.g);
  casadi_copy(d_nlp.lam, 246, d_nlp.lam_x);
  casadi_copy(d_nlp.lam + 246, 206, d_nlp.lam_g);
  if (d_nlp.f) casadi_copy(&d_nlp.objective, 1, d_nlp.f);
  if (d_nlp.lam_p) casadi_copy(d_nlp.lam_p, 278, d_nlp.lam_p);
  return 0;
  return 0;
}

